INSERT INTO constitution_documents(entity_name,title,version,constitutional_hierarchy,notes) SELECT 'OSANVAULT AFRICA LTD','ÒsánVault Africa Institutional Constitution','0.1','Constitutional governance framework subject to applicable company law, shareholder instruments, contracts, regulatory requirements and court orders.','Foundational draft only. Adoption requires appropriate corporate approvals and qualified legal review.' WHERE NOT EXISTS (SELECT 1 FROM constitution_documents WHERE title='ÒsánVault Africa Institutional Constitution');
INSERT INTO constitution_chapters(constitution_id,chapter_no,chapter_title,purpose) SELECT id,1,'Foundational Provisions','Name, purpose, objects, constitutional hierarchy and institutional identity.' FROM constitution_documents WHERE title='ÒsánVault Africa Institutional Constitution' AND NOT EXISTS (SELECT 1 FROM constitution_chapters WHERE chapter_no=1);
INSERT INTO constitution_chapters(constitution_id,chapter_no,chapter_title,purpose) SELECT id,2,'Ownership & Founding Interests','Founding interests, legitimate ownership protections and lawful indigenous/community safeguards.' FROM constitution_documents WHERE title='ÒsánVault Africa Institutional Constitution' AND NOT EXISTS (SELECT 1 FROM constitution_chapters WHERE chapter_no=2);
INSERT INTO constitution_chapters(constitution_id,chapter_no,chapter_title,purpose) SELECT id,3,'Governance Institutions','Board, committees, executives, secretary and independent assurance functions.' FROM constitution_documents WHERE title='ÒsánVault Africa Institutional Constitution' AND NOT EXISTS (SELECT 1 FROM constitution_chapters WHERE chapter_no=3);
