INSERT INTO constitution_chapters(constitution_id,chapter_no,chapter_title,purpose) SELECT id,5,'Reserved Matters','Transactions and decisions requiring enhanced board, shareholder or protected-interest approval.' FROM constitution_documents WHERE title='ÒsánVault Africa Institutional Constitution' AND NOT EXISTS (SELECT 1 FROM constitution_chapters WHERE chapter_no=5);
INSERT INTO constitution_chapters(constitution_id,chapter_no,chapter_title,purpose) SELECT id,6,'Finance, Assets & Stewardship','Capital, treasury, asset custody, procurement and stewardship controls.' FROM constitution_documents WHERE title='ÒsánVault Africa Institutional Constitution' AND NOT EXISTS (SELECT 1 FROM constitution_chapters WHERE chapter_no=6);
INSERT INTO constitution_chapters(constitution_id,chapter_no,chapter_title,purpose) SELECT id,7,'Risk, Compliance & Ethics','Risk appetite, compliance, audit, ethics, protected reporting and investigations.' FROM constitution_documents WHERE title='ÒsánVault Africa Institutional Constitution' AND NOT EXISTS (SELECT 1 FROM constitution_chapters WHERE chapter_no=7);
INSERT INTO constitution_chapters(constitution_id,chapter_no,chapter_title,purpose) SELECT id,8,'Continental Expansion','Subsidiaries, local participation, local-law supremacy and cross-border governance.' FROM constitution_documents WHERE title='ÒsánVault Africa Institutional Constitution' AND NOT EXISTS (SELECT 1 FROM constitution_chapters WHERE chapter_no=8);
INSERT INTO constitution_chapters(constitution_id,chapter_no,chapter_title,purpose) SELECT id,9,'Amendment, Succession & Continuity','Amendment classes, succession, continuity, deadlock and institutional resilience.' FROM constitution_documents WHERE title='ÒsánVault Africa Institutional Constitution' AND NOT EXISTS (SELECT 1 FROM constitution_chapters WHERE chapter_no=9);
INSERT INTO constitution_chapters(constitution_id,chapter_no,chapter_title,purpose) SELECT id,10,'Dissolution & Dispute Resolution','Dissolution, winding-up, dispute escalation and final constitutional safeguards.' FROM constitution_documents WHERE title='ÒsánVault Africa Institutional Constitution' AND NOT EXISTS (SELECT 1 FROM constitution_chapters WHERE chapter_no=10);
INSERT INTO constitution_articles(chapter_id,article_no,article_title,article_text,legal_basis,protected_interest,amendment_class) SELECT id,'1.1','Constitutional Supremacy Within the Institution','Material institutional actions should be consistent with the adopted constitution, applicable law, shareholder instruments, delegated authority and valid regulatory requirements.','Applicable company and regulatory law','Institutional integrity','Protected' FROM constitution_chapters WHERE chapter_no=1 AND NOT EXISTS (SELECT 1 FROM constitution_articles WHERE article_no='1.1');
INSERT INTO constitution_articles(chapter_id,article_no,article_title,article_text,legal_basis,protected_interest,amendment_class) SELECT id,'2.1','Founding Continuity','Legitimately documented founding interests should receive the protections specified in adopted legal instruments and should not be arbitrarily diluted through ordinary administrative action.','Adopted shareholder/ownership instruments and applicable law','Founding interests','Protected' FROM constitution_chapters WHERE chapter_no=2 AND NOT EXISTS (SELECT 1 FROM constitution_articles WHERE article_no='2.1');
INSERT INTO constitution_articles(chapter_id,article_no,article_title,article_text,legal_basis,protected_interest,amendment_class) SELECT id,'2.2','Indigenous and Community Rights','Projects affecting indigenous, customary, ancestral or community interests must identify applicable rights and lawful consent or consultation requirements before material execution.','Jurisdiction-specific law and valid instruments','Indigenous/community interests','Protected' FROM constitution_chapters WHERE chapter_no=2 AND NOT EXISTS (SELECT 1 FROM constitution_articles WHERE article_no='2.2');
INSERT INTO constitution_articles(chapter_id,article_no,article_title,article_text,legal_basis,protected_interest,amendment_class) SELECT id,'5.1','Reserved Matters Gate','A reserved matter must not be executed through ordinary delegated authority and must carry the approvals and evidence required by the adopted governance instruments.','Constitution and delegated authority instruments','Governance integrity','Protected' FROM constitution_chapters WHERE chapter_no=5 AND NOT EXISTS (SELECT 1 FROM constitution_articles WHERE article_no='5.1');
INSERT INTO constitution_articles(chapter_id,article_no,article_title,article_text,legal_basis,protected_interest,amendment_class) SELECT id,'8.1','Local Law Supremacy','The Group constitution establishes common institutional standards but does not override the mandatory law, regulatory authority, valid land regime, court order or legally recognized customary rights of a host jurisdiction.','Host-country law','Local sovereignty and rights','Protected' FROM constitution_chapters WHERE chapter_no=8 AND NOT EXISTS (SELECT 1 FROM constitution_articles WHERE article_no='8.1');
INSERT INTO constitutional_offices(constitution_id,office_code,office_title,mandate,appointment_route,accountability_route,removal_route,succession_route,independence_level) SELECT id,'BOA','Board of Directors','Strategic direction, oversight, fiduciary supervision and reserved-matter governance.','As provided by applicable law and adopted corporate instruments.','Shareholders and applicable law.','As provided by law and adopted instruments.','Board continuity plan.','High' FROM constitution_documents WHERE title='ÒsánVault Africa Institutional Constitution' AND NOT EXISTS (SELECT 1 FROM constitutional_offices WHERE office_code='BOA');
INSERT INTO constitutional_offices(constitution_id,office_code,office_title,mandate,appointment_route,accountability_route,removal_route,succession_route,independence_level) SELECT id,'SEC','Company Secretary / Governance Office','Constitutional records, resolutions, registers, governance calendar and procedural integrity.','Board/company law route.','Board.','Board/company law route.','Designated deputy or lawful replacement.','Independent control function' FROM constitution_documents WHERE title='ÒsánVault Africa Institutional Constitution' AND NOT EXISTS (SELECT 1 FROM constitutional_offices WHERE office_code='SEC');
INSERT INTO constitutional_offices(constitution_id,office_code,office_title,mandate,appointment_route,accountability_route,removal_route,succession_route,independence_level) SELECT id,'IA','Internal Audit / Assurance','Independent assurance over controls, risk, compliance and remediation.','Board/audit committee route.','Audit committee / Board.','Board/audit committee route.','Approved continuity arrangement.','Independent' FROM constitution_documents WHERE title='ÒsánVault Africa Institutional Constitution' AND NOT EXISTS (SELECT 1 FROM constitutional_offices WHERE office_code='IA');
INSERT INTO constitutional_offices(constitution_id,office_code,office_title,mandate,appointment_route,accountability_route,removal_route,succession_route,independence_level) SELECT id,'ETH','Ethics & Protected Reporting Office','Protected reporting, conflicts, investigations and anti-retaliation oversight.','Board-approved route.','Independent board committee / Board.','Board-approved route.','Approved continuity arrangement.','Independent' FROM constitution_documents WHERE title='ÒsánVault Africa Institutional Constitution' AND NOT EXISTS (SELECT 1 FROM constitutional_offices WHERE office_code='ETH');
INSERT INTO constitutional_amendment_rules(constitution_id,amendment_class,subject_scope,proposal_threshold,approval_threshold,consultation_requirement) SELECT id,'Protected','Founding protections, indigenous/community safeguards, constitutional hierarchy, reserved-matter protections and core institutional continuity.','Board or shareholder threshold defined by adopted instruments.','Enhanced shareholder/board threshold plus required protected-interest consent where legally applicable.','Legal review and affected-interest consultation where required.' FROM constitution_documents WHERE title='ÒsánVault Africa Institutional Constitution' AND NOT EXISTS (SELECT 1 FROM constitutional_amendment_rules WHERE amendment_class='Protected');
INSERT INTO constitutional_amendment_rules(constitution_id,amendment_class,subject_scope,proposal_threshold,approval_threshold,consultation_requirement) SELECT id,'Ordinary','Administrative, procedural and operational provisions not classified as Protected.','Board or authorized proposer.','Approval route defined by adopted instruments.','Legal review where required.' FROM constitution_documents WHERE title='ÒsánVault Africa Institutional Constitution' AND NOT EXISTS (SELECT 1 FROM constitutional_amendment_rules WHERE amendment_class='Ordinary');