CREATE TABLE IF NOT EXISTS constitution_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, title text NOT NULL, version text NOT NULL DEFAULT '0.1', status text NOT NULL DEFAULT 'Draft', adoption_status text NOT NULL DEFAULT 'Not Adopted', jurisdiction text NOT NULL DEFAULT 'Nigeria', constitutional_hierarchy text, legal_review_status text NOT NULL DEFAULT 'Required', effective_date date, custodian_role text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS constitution_chapters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), constitution_id uuid REFERENCES constitution_documents(id) ON DELETE CASCADE, chapter_no integer NOT NULL, chapter_title text NOT NULL, purpose text, status text NOT NULL DEFAULT 'Draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS constitution_articles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), chapter_id uuid REFERENCES constitution_chapters(id) ON DELETE CASCADE, article_no text NOT NULL, article_title text NOT NULL, article_text text NOT NULL, legal_basis text, protected_interest text, amendment_class text NOT NULL DEFAULT 'Ordinary', legal_review_required boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'Draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS constitutional_offices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), constitution_id uuid REFERENCES constitution_documents(id) ON DELETE CASCADE, office_code text NOT NULL, office_title text NOT NULL, mandate text NOT NULL, appointment_route text, accountability_route text, removal_route text, succession_route text, independence_level text, status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS constitutional_amendment_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), constitution_id uuid REFERENCES constitution_documents(id) ON DELETE CASCADE, amendment_class text NOT NULL, subject_scope text NOT NULL, proposal_threshold text NOT NULL, approval_threshold text NOT NULL, consultation_requirement text, legal_review_required boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS constitutional_review_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), constitution_id uuid REFERENCES constitution_documents(id) ON DELETE CASCADE, review_type text NOT NULL, reviewer_role text, review_status text NOT NULL DEFAULT 'Open', findings text, required_action text, reviewed_at timestamptz, evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
